    local function saimAlive(player)
        local char = player and player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")
        return hum ~= nil and hum.Health > 0 and root ~= nil
    end

    local function saimGun()
        local char = localPlayer.Character
        local gun = char and char:FindFirstChild("Gun")
        if gun then
            return gun
        end
        local bp = localPlayer:FindFirstChild("Backpack")
        return bp and bp:FindFirstChild("Gun")
    end

    local function saimLocalRoot()
        local char = localPlayer.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end

    local function saimRoundData()
        local data
        pcall(function()
            local rs = game:GetService("ReplicatedStorage")
            local mod = rs:FindFirstChild("Modules") and rs.Modules:FindFirstChild("CurrentRoundClient")
            if mod then
                data = require(mod).GetLatestPlayerData()
            end
        end)
        return type(data) == "table" and data or nil
    end

    -- цель: убийца (данные ролей, фолбэк — fn72 по ножу)
    local function saimTargetChar()
        if not saimAlive(localPlayer) then
            return nil
        end
        local data = saimRoundData()
        if data then
            for _, plr in ipairs(Players2:GetPlayers()) do
                local info = data[plr.Name]
                if info and info.Role == "Murderer" and info.Dead ~= true and info.Killed ~= true then
                    local char = plr.Character
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    if char and hum and hum.Health > 0 then
                        return char
                    end
                end
            end
        end
        local plr = fn72()
        return plr and plr.Character or nil
    end

    -- ===== V3: адаптивная сетевая модель (rtt/jitter/interp/hbias) =====
    local saimNet = {
        rtt = 0.1, jit = 0.01, interp = 0.08, wire = 0, up = 0.05,
        n = 0, lastL = 0, hbias = 0, hn = 0,
        tHist = {}, mHist = {}, rawHist = {}, char = nil, pend = nil,
    }

    local function saimRtt()
        return math.max(saimNet.rtt, saimNet.wire)
    end

    local function saimPing()
        local q
        local ok, v = pcall(function()
            return localPlayer:GetNetworkPing()
        end)
        if ok and type(v) == "number" and v == v and v >= 0 and v < 2 then
            q = v
        end
        local ok2, v2 = pcall(function()
            return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
        end)
        if ok2 and type(v2) == "number" and v2 == v2 and v2 >= 0 and v2 < 2000 then
            q = q and math.max(q, v2 / 1000) or v2 / 1000
        end
        return q
    end

    local saimV3 = {}
    function saimV3.leadT()
        return math.clamp(saimRtt() + saimNet.interp + math.clamp(saimNet.hbias, -0.08, 0.2) + saimCfg.predEx, 0.02, 0.6)
    end
    function saimV3.jitter()
        return saimNet.jit
    end
    function saimV3.uplink()
        return saimNet.up
    end
    function saimV3.stats()
        return {
            rtt = saimNet.rtt, wire = saimNet.wire, jit = saimNet.jit,
            interp = saimNet.interp, up = saimNet.up, n = saimNet.n,
            hbias = saimNet.hbias, hn = saimNet.hn, lead = saimV3.leadT(),
        }
    end
    function saimV3.note(startP, endP, char, vel)
        local dir = endP - startP
        if dir.Magnitude < 0.5 then
            saimNet.pend = nil
            return
        end
        saimNet.pend = {
            t = os.clock(), o = startP, u = dir.Unit, char = char,
            v = vel or Vector3.new(0, 0, 0), rh = saimNet.rawHist,
            base = saimRtt() + saimNet.interp,
        }
    end
    function saimV3.onFired(startP, endP, hitPart)
        local pend = saimNet.pend
        if not pend then
            return
        end
        if typeof(startP) == "Vector3" then
            pend.startP = startP
        end
        if typeof(endP) == "Vector3" and typeof(hitPart) == "Instance" and pend.char and hitPart:IsDescendantOf(pend.char) then
            pend.endP = endP
            local hw = 0.5
            pcall(function()
                local cf, sz = hitPart.CFrame, hitPart.Size
                hw = 0.5 * (math.abs(cf.RightVector:Dot(pend.u)) * sz.X + math.abs(cf.UpVector:Dot(pend.u)) * sz.Y + math.abs(cf.LookVector:Dot(pend.u)) * sz.Z)
            end)
            pend.hw = math.clamp(hw, 0.2, 1.2)
        end
        local dt = os.clock() - pend.t
        if dt > 0.005 and dt < 1.2 then
            if saimNet.wire > 0 then
                saimNet.jit = saimLerp(saimNet.jit, math.abs(dt - saimNet.wire), 0.2)
            end
            saimNet.wire = saimNet.wire > 0 and saimLerp(saimNet.wire, dt, 0.25) or dt
        end
    end

    local function saimWinVel(hist, idx, hWin, vWin)
        local lo, hi
        for i = idx, 1, -1 do
            if not lo and hist[idx].t - hist[i].t >= hWin then
                lo = hist[i]
            end
            if lo and lo.t - hist[i].t >= vWin then
                hi = hist[i]
                break
            end
        end
        if not (hi and lo) then
            return nil
        end
        local dt = lo.t - hi.t
        if dt < 0.03 then
            return nil
        end
        local v = (lo.p - hi.p) / dt
        return Vector3.new(v.X, 0, v.Z), (lo.t + hi.t) * 0.5
    end

    function saimV3.turnRate()
        local hist = saimNet.tHist
        local n = #hist
        if n < 5 then
            return 0
        end
        local v1, t1 = saimWinVel(hist, n, 0, 0.12)
        local v2, t2 = saimWinVel(hist, n, 0.12, 0.12)
        if not (v1 and v2 and t1 and t2) then
            return 0
        end
        if v1.Magnitude < 4 or v2.Magnitude < 4 then
            return 0
        end
        local u2, u1 = v2.Unit, v1.Unit
        local perp = Vector3.new(-u2.Z, 0, u2.X)
        local ang = math.atan2(perp:Dot(u1), u2:Dot(u1))
        local dt = t1 - t2
        if dt < 0.03 then
            return 0
        end
        local rate = ang / dt
        if rate ~= rate then
            return 0
        end
        return math.clamp(rate, -6.0, 6)
    end

    function saimV3.arcLead(vel, lead)
        local spd = vel.Magnitude
        if spd < 0.001 or lead <= 0 then
            return Vector3.new(0, 0, 0), vel
        end
        local unit = vel.Unit
        local rate = saimV3.turnRate()
        if math.abs(rate) < 0.35 then
            return vel * lead, vel
        end
        local perp = Vector3.new(-unit.Z, 0, unit.X)
        local radius = spd / rate
        local theta = math.clamp(rate * lead, -1.0, 1)
        local disp = unit * (radius * math.sin(theta)) + perp * (radius * (1 - math.cos(theta)))
        local newVel = (unit * math.cos(theta) + perp * math.sin(theta)) * spd
        return disp, newVel
    end

    local saimBodyParts = { HumanoidRootPart = true, UpperTorso = true, LowerTorso = true, Torso = true, Head = true }
    function saimV3.bestPart(char, dir)
        if not char or typeof(dir) ~= "Vector3" or dir.Magnitude < 0.001 then
            return nil, 0
        end
        local unit = dir.Unit
        local ref = math.abs(unit.Y) > 0.9 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)
        local side = unit:Cross(ref)
        if side.Magnitude < 0.001 then
            return nil, 0
        end
        side = side.Unit
        local up = unit:Cross(side).Unit
        local best, bestScore
        for _, part in ipairs(char:GetChildren()) do
            if part:IsA("BasePart") and saimBodyParts[part.Name] and part.Transparency < 1 then
                local cf, sz = part.CFrame, part.Size
                local hx, hy, hz = sz.X * 0.5, sz.Y * 0.5, sz.Z * 0.5
                local r, u, l = cf.RightVector, cf.UpVector, cf.LookVector
                local a = hx * math.abs(r:Dot(side)) + hy * math.abs(u:Dot(side)) + hz * math.abs(l:Dot(side))
                local b = hx * math.abs(r:Dot(up)) + hy * math.abs(u:Dot(up)) + hz * math.abs(l:Dot(up))
                local score = math.min(a, b)
                if not bestScore or score > bestScore then
                    best, bestScore = part, score
                end
            end
        end
        return best, bestScore or 0
    end

    function saimV3.bestAxis(char, vel)
        local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
        if not root then
            return nil, nil, 0
        end
        local cf = root.CFrame
        local axes = {
            Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z),
            Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z),
        }
        if vel and vel.Magnitude > 0.1 then
            axes[#axes + 1] = Vector3.new(vel.X, 0, vel.Z)
        end
        local bDir, bPart, bScore
        for _, ax in ipairs(axes) do
            if ax.Magnitude > 0.1 then
                local unit = ax.Unit
                local part, score = saimV3.bestPart(char, unit)
                if part and (not bScore or score > bScore) then
                    bDir, bPart, bScore = unit, part, score
                end
            end
        end
        return bDir, bPart, bScore or 0
    end

    local function saimMedian(hist, from, to)
        local xs, ys, zs = {}, {}, {}
        for i = from, to do
            local p = hist[i].p
            xs[#xs + 1] = p.X
            ys[#ys + 1] = p.Y
            zs[#zs + 1] = p.Z
        end
        if #xs == 0 then
            return nil
        end
        table.sort(xs); table.sort(ys); table.sort(zs)
        local mid = math.floor(#xs / 2) + 1
        return Vector3.new(xs[mid], ys[mid], zs[mid])
    end

    function saimV3.jumpCycle()
        local hist = saimNet.rawHist
        local n = #hist
        if n < 8 then
            return false, 0
        end
        local newest = hist[n].t
        local from = 1
        for i = n, 1, -1 do
            if newest - hist[i].t > 0.6 then
                from = i + 1
                break
            end
        end
        if n - from + 1 < 8 then
            return false, 0
        end
        local lo, hi = math.huge, -math.huge
        local flips, lastSign = 0, 0
        for i = from + 1, n do
            local y = hist[i].p.Y
            if y < lo then lo = y end
            if y > hi then hi = y end
            local d = y - hist[i - 1].p.Y
            if math.abs(d) > 0.05 then
                local sign = d > 0 and 1 or -1
                if lastSign ~= 0 and sign ~= lastSign then
                    flips = flips + 1
                end
                lastSign = sign
            end
        end
        local range = hi - lo
        return range > 4 and flips >= 2, range
    end

    function saimV3.resolve()
        local hist = saimNet.rawHist
        local n = #hist
        if n < 6 then
            return nil, "none"
        end
        local newest = hist[n].t
        local from = 1
        for i = n, 1, -1 do
            if newest - hist[i].t > 0.35 then
                from = i + 1
                break
            end
        end
        if n - from + 1 < 5 then
            return nil, "none"
        end
        local med = saimMedian(hist, from, n)
        if not med then
            return nil, "none"
        end
        local sum, count, maxD, far = 0, 0, 0, 0
        for i = from, n do
            local d = (hist[i].p - med).Magnitude
            sum = sum + d; count = count + 1
            if d > maxD then maxD = d end
            if d > 50 then far = far + 1 end
        end
        local avg = count > 0 and sum / count or 0
        if far > 0 and maxD > 100 then
            local tight = {}
            for i = from, n do
                if (hist[i].p - med).Magnitude <= 25 then
                    tight[#tight + 1] = hist[i]
                end
            end
            if #tight >= 3 then
                return saimMedian(tight, 1, #tight), "blink"
            end
            return nil, "none"
        end
        local travel = (hist[n].p - hist[from].p).Magnitude
        if avg > 3 and travel < avg * 1.5 then
            return med, "jitter"
        end
        return nil, "clean"
    end

    -- ===== velocity цели: история + AssemblyLinearVelocity с анти-десync =====
    local function saimVel(char, root, acc)
        local vel = root.AssemblyLinearVelocity or Vector3.new(0, 0, 0)
        if vel.Magnitude ~= vel.Magnitude then
            vel = Vector3.new(0, 0, 0)
        end
        acc = Vector3.new(0, 0, 0)
        if saimCfg.resolver then
            local hist = saimNet.tHist
            local n = #hist
            if n >= 2 then
                local newest = hist[n]
                local back = n
                while back > 1 and newest.t - hist[back].t < 0.1 do
                    back = back - 1
                end
                local dt = newest.t - hist[back].t
                if dt >= 0.06 then
                    local dv = (newest.p - hist[back].p) / dt
                    if dv.Magnitude == dv.Magnitude and dv.Magnitude < 400 then
                        vel = dv
                    end
                end
            end
            local server = root.AssemblyLinearVelocity or Vector3.new(0, 0, 0)
            if server.Magnitude ~= server.Magnitude then
                server = Vector3.new(0, 0, 0)
            end
            local flat = Vector3.new(vel.X, 0, vel.Z)
            local cap = flat.Magnitude * 1.5 + 8
            if server.Magnitude > cap and server.Magnitude > 0.001 then
                vel = server.Unit * cap
            else
                vel = server
            end
        end
        local flat = Vector3.new(vel.X, 0, vel.Z)
        if flat.Magnitude ~= flat.Magnitude then
            return Vector3.new(0, 0, 0), acc
        end
        if flat.Magnitude > 400 then
            flat = flat.Unit * 400
        end
        return flat, acc
    end

    -- ===== raycast-хелперы =====
    local saimPassthrough = { Effect = true, Rocket = true, Bullet = true, Handle = true, Coin = true }

    local function saimJumpClear(char, pos)
        local height = 11
        pcall(function()
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = { char, localPlayer.Character }
            local hit = saimWS:Raycast(pos + Vector3.new(0, 1, 0), Vector3.new(0, 11, 0), params)
            if hit then
                height = math.max(2.5, hit.Position.Y - pos.Y - 0.8)
            end
        end)
        return height
    end

    local function saimOtherPositions(excludeChar)
        local list = {}
        pcall(function()
            for _, plr in ipairs(Players2:GetPlayers()) do
                if plr ~= localPlayer then
                    local char = plr.Character
                    if char and char ~= excludeChar then
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        local part = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
                        if hum and hum.Health > 0 and part then
                            list[#list + 1] = part.Position
                        end
                    end
                end
            end
        end)
        return list
    end

    -- проверка, что на пути нет союзников (для рельсов-«рэйлов»)
    local function saimFriendlyClear(others, startP, endP, excludeChar)
        if #others == 0 then
            return true
        end
        local seg = endP - startP
        if seg.Magnitude < 0.0001 then
            return true
        end
        local unit = seg.Unit
        local dist = 2500
        pcall(function()
            local filter = { excludeChar, localPlayer.Character }
            pcall(function()
                for _, tagged in ipairs(game:GetService("CollectionService"):GetTagged("WeaponPassthrough")) do
                    filter[#filter + 1] = tagged
                end
            end)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.IgnoreWater = true
            for _ = 1, 10 do
                params.FilterDescendantsInstances = filter
                local hit = saimWS:Raycast(startP, unit * dist, params)
                if not hit then
                    return
                end
                if hit.Instance and (hit.Instance.Transparency == 1 or saimPassthrough[hit.Instance.Name]) then
                    filter[#filter + 1] = hit.Instance
                else
                    dist = (hit.Position - startP).Magnitude + 1
                    return
                end
            end
        end)
        local segFull = unit * dist
        local len2 = segFull:Dot(segFull)
        for _, pos in ipairs(others) do
            local t = 0
            if len2 > 0.000001 then
                t = math.clamp((pos - startP):Dot(segFull) / len2, 0, 1)
            end
            if (pos - (startP + segFull * t)).Magnitude < 5 then
                return false
            end
        end
        return true
    end

    -- FOV-проверка (экранная окружность) — экспорт для UI/хука
    function saimFovOK(char)
        if not saimCfg.fovOn then
            return true
        end
        local size = tonumber(saimCfg.fovSize) or 220
        if size >= 1500 then
            return char ~= nil
        end
        local part = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head"))
        if not part then
            return false
        end
        local cam = saimWS.CurrentCamera
        if not cam then
            return true
        end
        local ok, res = pcall(function()
            local vp, onScreen = cam:WorldToViewportPoint(part.Position)
            if not onScreen or vp.Z <= 0 then
                return false
            end
            local vs = cam.ViewportSize
            local dx, dy = vp.X - vs.X * 0.5, vp.Y - vs.Y * 0.5
            return dx * dx + dy * dy <= size * size
        end)
        return ok and res or false
    end

    local function saimTransparency(part)
        return part.Transparency
    end

    -- трассировка сквозь прозрачные/проходимые части (для wallbang-LOS)
    local function saimWallRay(startP, dir, extraFilter)
        local filter = { localPlayer.Character }
        if extraFilter then
            for _, item in ipairs(extraFilter) do
                filter[#filter + 1] = item
            end
        end
        pcall(function()
            for _, tagged in ipairs(game:GetService("CollectionService"):GetTagged("WeaponPassthrough")) do
                filter[#filter + 1] = tagged
            end
        end)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.IgnoreWater = true
        for _ = 1, 10 do
            params.FilterDescendantsInstances = filter
            local hit = saimWS:Raycast(startP, dir, params)
            if not hit then
                return nil
            end
            if hit.Instance and (saimTransparency(hit.Instance) == 1 or saimPassthrough[hit.Instance.Name]) then
                filter[#filter + 1] = hit.Instance
            else
                return hit
            end
        end
        return nil
    end

    -- подтверждение LOS: попадает ли луч в цель (с учётом прозрачных стен)
    local function saimLosHit(startP, endPos, targetChar, others, targetRoot)
        local delta = endPos - startP
        if delta.Magnitude < 0.5 then
            return false
        end
        local confirmed = false
        pcall(function()
            local first = saimWallRay(startP, delta.Unit * (delta.Magnitude + 45), { targetChar })
            confirmed = first ~= nil and first.Instance:IsDescendantOf(targetChar)
            if not confirmed and targetRoot then
                local direct = first ~= nil and (first.Position - startP).Magnitude < delta.Magnitude - 0.5
                if not direct then
                    local d2 = targetRoot.Position - startP
                    if d2.Magnitude >= 0.5 then
                        local second = saimWallRay(startP, d2.Unit * (d2.Magnitude + 45), { targetChar })
                        confirmed = second ~= nil and second.Instance:IsDescendantOf(targetChar)
                    end
                end
            end
        end)
        if not confirmed then
            return false
        end
        return saimFriendlyClear(others or {}, startP, endPos, targetChar)
    end

    -- ===== rельс-планировщик k() =====
    local function saimMuzzlePos()
        local root = saimLocalRoot()
        if not root then
            return nil
        end
        local att = root:FindFirstChild("GunRaycastAttachment")
        local pos = att and att.WorldCFrame.Position or root.Position
        local up = saimV3.uplink()
        if up > 0 then
            local v = root.AssemblyLinearVelocity
            if typeof(v) == "Vector3" and v.Magnitude > 8 then
                pos = pos + Vector3.new(v.X, 0, v.Z) * math.clamp(up, 0, 0.3)
            end
        end
        return pos, root
    end

    local saimAimState = { char = nil, t = 0, u = nil }
    local saimTurnState = { t = 0, w = 0 }

    local function saimPlan(char, manual)
        if not char or not char.Parent then
            return nil
        end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then
            return nil
        end
        local muzzle = saimMuzzlePos()
        if not muzzle then
            return nil
        end
        local targetRoot = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
        local resolveOff, resolveMode = Vector3.new(0, 0, 0), "off"
        if saimCfg.resolver and targetRoot then
            local ok, corrected, mode = pcall(saimV3.resolve)
            if ok then
                resolveMode = mode or "none"
                if typeof(corrected) == "Vector3" then
                    resolveOff = corrected - targetRoot.Position
                end
            end
        end
        getgenv().__taleResolveMode = resolveMode
        if not targetRoot then
            return nil
        end
        local head = char:FindFirstChild("Head")
        local lead = saimV3.leadT()
        local vel = saimVel(char, targetRoot)
        if vel.Magnitude ~= vel.Magnitude then
            vel = Vector3.new(0, 0, 0)
        end
        if resolveMode == "jitter" and resolveOff.Magnitude > 0.01 then
            local flat = Vector3.new(vel.X, 0, vel.Z)
            if flat.Magnitude > 1 then
                local b = flat.Unit
                local comp = resolveOff:Dot(b)
                if comp < 0 then
                    resolveOff = resolveOff - b * comp
                end
            end
        end
        local airVel, isAir = 0, false
        pcall(function()
            local st = hum:GetState()
            if st == Enum.HumanoidStateType.Jumping or st == Enum.HumanoidStateType.Freefall then
                local vy = targetRoot.AssemblyLinearVelocity.Y
                local bigJump = math.abs(vy) > 20
                local noGround = false
                pcall(function()
                    local params = RaycastParams.new()
                    params.FilterType = Enum.RaycastFilterType.Exclude
                    params.FilterDescendantsInstances = { char, localPlayer.Character }
                    params.IgnoreWater = true
                    noGround = saimWS:Raycast(targetRoot.Position, Vector3.new(0, -4.5, 0), params) == nil
                end)
                if noGround or math.abs(vy) > 6 and (bigJump or hum.FloorMaterial == Enum.Material.Air) then
                    isAir = true
                    airVel = math.clamp(vy, -140.0, 140)
                end
            end
        end)
        if not isAir then
            pcall(function()
                local st = hum:GetState()
                if st == Enum.HumanoidStateType.Swimming or st == Enum.HumanoidStateType.Climbing or st == Enum.HumanoidStateType.Seated or st == Enum.HumanoidStateType.PlatformStanding then
                    return
                end
                local vy = targetRoot.AssemblyLinearVelocity.Y
                if math.abs(vy) > 5 then
                    local params = RaycastParams.new()
                    params.FilterType = Enum.RaycastFilterType.Exclude
                    params.FilterDescendantsInstances = { char, localPlayer.Character }
                    params.IgnoreWater = true
                    if saimWS:Raycast(targetRoot.Position, Vector3.new(0, -4.5, 0), params) == nil then
                        isAir = true
                        airVel = math.clamp(vy, -140.0, 140)
                    end
                end
            end)
        end
        local jumpAir = false
        pcall(function()
            local ok, air = pcall(saimV3.jumpCycle)
            if ok and air then
                jumpAir = true
            end
        end)
        local leadVec, velDir = vel * lead, vel
        do
            local ok, disp, newVel = pcall(saimV3.arcLead, vel, lead)
            if ok and typeof(disp) == "Vector3" then
                leadVec = disp
                if typeof(newVel) == "Vector3" and newVel.Magnitude > 0.1 then
                    velDir = newVel
                end
            end
        end
        do
            local acc = targetRoot.AssemblyLinearVelocity
            if typeof(acc) == "Vector3" and acc.Magnitude == acc.Magnitude and acc.Magnitude > 1 then
                local rate = 0
                pcall(function()
                    rate = saimV3.turnRate()
                end)
                if type(rate) ~= "number" or rate ~= rate then
                    rate = 0
                end
                if math.abs(rate) < 0.35 then
                    local flat = Vector3.new(acc.X, 0, acc.Z)
                    local disp = flat * (0.5 * lead * lead)
                    local cap = math.max(1.5, vel.Magnitude * lead * 0.6)
                    if disp.Magnitude > cap then
                        disp = disp.Unit * cap
                    end
                    leadVec = leadVec + disp
                    velDir = velDir + rate * lead
                end
            end
        end
        local leadCap = 45
        if vel.Magnitude > 0 then
            leadCap = math.max(45, vel.Magnitude * 0.6 + 12)
        end
        if leadVec.Magnitude > leadCap then
            leadVec = leadVec.Unit * leadCap
        end
        local airDrop = isAir and math.clamp(airVel * lead - 98.1 * lead * lead, -24.0, 9) or 0
        if airDrop < -1.0 then
            pcall(function()
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances = { char, localPlayer.Character }
                params.IgnoreWater = true
                local hit = saimWS:Raycast(targetRoot.Position + resolveOff, Vector3.new(0, airDrop - 3, 0), params)
                if hit then
                    airDrop = math.max(airDrop, hit.Position.Y + 1.8 - targetRoot.Position.Y)
                end
            end)
        end
        local aimDelta = Vector3.new(leadVec.X, airDrop, leadVec.Z)
        local aimPoint = targetRoot.Position + resolveOff + aimDelta
        local spd = vel.Magnitude
        local dist = (aimPoint - muzzle).Magnitude
        local facing = velDir.Magnitude >= 3 and velDir.Unit or nil
        if facing then
            pcall(function()
                local flat = Vector3.new(targetRoot.CFrame.LookVector.X, 0, targetRoot.CFrame.LookVector.Z)
                if flat.Magnitude > 0.1 and flat.Unit:Dot(facing) > 0.85 then
                    facing = flat.Unit
                end
            end)
        end
        local continuity = 1
        local now = os.clock()
        if spd >= 3 and facing and not manual then
            if saimAimState.char ~= char or not saimAimState.u then
                saimAimState.char, saimAimState.t, saimAimState.u = char, now, facing
            else
                continuity = facing:Dot(saimAimState.u)
                if now - saimAimState.t > 0.12 then
                    saimAimState.t, saimAimState.u = now, facing
                end
            end
        elseif spd < 3 then
            saimAimState.u = nil
        end
        local contThreshold = (dist < 0.62) and 0.82 or 0.55
        local snapReject = false
        if not manual and continuity < contThreshold then
            local rate = 0
            pcall(function()
                rate = saimV3.turnRate()
            end)
            if type(rate) ~= "number" or rate ~= rate then
                rate = 0
            end
            local ar = math.abs(rate)
            if ar >= 0.35 and ar <= 6 then
                local prevW, dt = saimTurnState.w, now - saimTurnState.t
                if dt >= 0.1 then
                    saimTurnState.t, saimTurnState.w = now, rate
                end
                if prevW ~= 0 and prevW > 0 == (rate > 0) and math.abs(ar - math.abs(prevW)) <= ar * 0.25 then
                    snapReject = true
                end
            else
                saimTurnState.w = 0
            end
        end
        if not manual and not snapReject and spd >= 3 and continuity < contThreshold then
            return { ok = false, P = aimPoint, Pm = aimPoint }
        end
        local wallbang = saimCfg.wallbang == true
        local losClear, tooClose = true, false
        do
            local delta = aimPoint - muzzle
            if delta.Magnitude > 0.5 then
                local first
                pcall(function()
                    first = saimWallRay(muzzle, delta, { char })
                end)
                if first then
                    local h = (first.Position - muzzle).Magnitude
                    if h < delta.Magnitude - 0.5 then
                        losClear = false
                    end
                    if h < 3 then
                        tooClose = true
                    end
                end
            end
        end
        local rails = {}
        if isAir then
            local fall = Vector3.new(vel.X, airVel - 196.2 * lead, vel.Z)
            if fall.Magnitude > 3 then
                local unit = fall.Unit
                local margin = math.clamp(fall.Magnitude * ((saimV3.jitter() * 2 + 0.06)) + 1.5, 2.5, math.max(11, fall.Magnitude * 0.35))
                local back = margin + math.max(aimDelta:Dot(unit), 0) + 1.5
                rails[#rails + 1] = { aimPoint - unit * back, aimPoint + unit * margin, "railAir" }
                rails[#rails + 1] = { aimPoint + unit * margin, aimPoint - unit * back, "railAirR" }
            end
        end
        if spd >= 3 and facing then
            local railBase = targetRoot.Position + resolveOff + Vector3.new(0, airDrop, 0)
            local railAim = aimPoint
            do
                local flat = Vector3.new(aimDelta.X, 0, aimDelta.Z)
                local dir = facing
                if flat.Magnitude > 0.1 then
                    dir = flat.Unit
                end
                local ok, part = pcall(saimV3.bestPart, char, dir)
                if ok and part then
                    railAim = part.Position + resolveOff + aimDelta
                end
                local margin = math.clamp(spd * (saimV3.jitter() * 2 + 0.06) + 1.5, 2.5, math.max(11, spd * 0.35))
                local back = margin + math.max(Vector3.new(aimDelta.X, 0, aimDelta.Z):Dot(dir), 0) + 1.5
                rails[#rails + 1] = { railAim - dir * back, railAim + dir * margin, "railV3" }
                rails[#rails + 1] = { railAim + dir * margin, railAim - dir * back, "railV3R" }
            end
            local P = math.clamp(leadVec.Magnitude + 1.5, 2, 6)
            rails[#rails + 1] = { railBase - facing * 1, railBase + facing * P, "rail" }
            rails[#rails + 1] = { railBase + facing * P, railBase - facing * 1, "railR" }
        end
        do
            local ok, axis, part = pcall(saimV3.bestAxis, char, vel)
            if ok and typeof(axis) == "Vector3" and part then
                local P = part.Position + resolveOff + aimDelta
                rails[#rails + 1] = { P + axis * 4, P - axis * 4, "broad" }
                rails[#rails + 1] = { P - axis * 4, P + axis * 4, "broadR" }
            end
        end
        if jumpAir and spd < 20 then
            local hopH = saimJumpClear(char, aimPoint)
            rails[#rails + 1] = { aimPoint + Vector3.new(0.01, math.max(hopH, 4), 0.01), aimPoint, "hopCol" }
        end
        rails[#rails + 1] = { muzzle, aimPoint, "torso" }
        if head then
            rails[#rails + 1] = { muzzle, head.Position + resolveOff + aimDelta, "head" }
        end
        if wallbang then
            local back = muzzle - aimPoint
            local unit = back.Magnitude > 0.5 and back.Unit or Vector3.new(0, 0, 1)
            rails[#rails + 1] = { aimPoint + unit * 3, aimPoint, "wbThru" }
            local colH = saimJumpClear(char, aimPoint)
            rails[#rails + 1] = { aimPoint + Vector3.new(0.01, math.max(colH, 3), 0.01), aimPoint - Vector3.new(0, 4, 0), "wbCol" }
        end
        if not wallbang and not losClear then
            local kept = {}
            for _, rail in ipairs(rails) do
                if (rail[1] - muzzle).Magnitude < 0.5 then
                    kept[#kept + 1] = rail
                end
            end
            rails = kept
        end
        local others = saimOtherPositions(char)
        local bestStart, bestEnd, bestTag, bestScore
        local railSet = { railAir = true, railAirR = true, railV3 = true, railV3R = true, rail = true, railR = true }
        local claimed = {}
        local picked = false
        if resolveOff.Magnitude > 0.01 and not tooClose and saimFriendlyClear(others, muzzle, aimPoint, char) then
            if wallbang or losClear then
                bestStart, bestEnd, bestTag = muzzle, aimPoint, "resolve:" .. resolveMode
                picked = true
            end
        end
        local mirror = { railAirR = "railAir", railV3R = "railV3", railR = "rail", broadR = "broad" }
        for _, rail in ipairs(rails) do
            if picked then
                break
            end
            if rail[3] ~= "wbThru" and rail[3] ~= "wbCol" and not (mirror[rail[3]] and claimed[mirror[rail[3]]]) then
                if saimLosHit(rail[1], rail[2], char, others, targetRoot) then
                    claimed[rail[3]] = true
                    local dir = rail[2] - rail[1]
                    dir = dir.Magnitude > 0.001 and dir.Unit or Vector3.new(0, 0, 1)
                    local base = 0.45
                    do
                        local ok, part, score = pcall(saimV3.bestPart, char, dir)
                        if ok and type(score) == "number" and score > 0 then
                            base = score
                        end
                    end
                    local vert = 1 - 0.6 * math.abs(dir.Y)
                    local railBonus = 0
                    if railSet[rail[3]] then
                        local v3 = Vector3.new(vel.X, isAir and airVel - 196.2 * lead or 0, vel.Z)
                        local k = (saimV3.jitter() or 0.03) + 0.02
                        railBonus = math.clamp(math.abs(v3:Dot(dir)) * k, 0.4, 1.4)
                    end
                    local score = base * vert + railBonus
                    if not bestStart or score > bestScore + 0.05 then
                        bestStart, bestEnd, bestTag, bestScore = rail[1], rail[2], rail[3], score
                    end
                    if bestScore >= 2.2 then
                        break
                    end
                end
            end
        end
        if not bestStart then
            for _, rail in ipairs(rails) do
                local isWb = rail[3] == "wbThru" or rail[3] == "wbCol"
                local ok
                if isWb then
                    ok = saimFriendlyClear(others, rail[1], rail[2], char) and saimFriendlyClear(others, muzzle, aimPoint, char)
                else
                    ok = saimLosHit(rail[1], rail[2], char, others, targetRoot)
                end
                if ok then
                    bestStart, bestEnd, bestTag = rail[1], rail[2], rail[3]
                    break
                end
            end
        end
        if not bestStart then
            if manual and saimFriendlyClear(others, muzzle, aimPoint, char) then
                return { ok = true, origin = muzzle, aim = aimPoint, P = aimPoint, Pm = aimPoint, mode = "blind", spd = spd, ld = leadVec.Magnitude }
            end
            return { ok = false, P = aimPoint, Pm = aimPoint }
        end
        return { ok = true, origin = bestStart, aim = bestEnd, P = aimPoint, Pm = bestEnd, mode = bestTag, spd = spd, ld = leadVec.Magnitude }
    end

    -- ===== fire: план + выстрел через Gun.Shoot =====
    local saimConfirm = { confirmT = 0, lastHit = nil, lastEnd = nil, lastStart = nil, pending = nil, tries = 0, armed = false }

    local function saimFireSpread(char, retry, manual)
        local gun = saimGun()
        local shoot = gun and gun:FindFirstChild("Shoot")
        if not shoot then
            return false
        end
        local plan = saimPlan(char, manual)
        if not (plan and plan.ok) then
            return false
        end
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not (char.Parent and hum and hum.Health > 0 and saimGun()) then
            return false
        end
        local origin, aimPos = plan.origin, plan.aim
        getgenv().__taleAimBypass = true
        local cf = (aimPos - origin).Magnitude < 0.1 and CFrame.new(origin) or CFrame.new(origin, aimPos)
        local ok = pcall(function()
            shoot:FireServer(cf, CFrame.new(aimPos))
        end)
        getgenv().__taleAimBypass = false
        if ok then
            pcall(saimV3.note, origin, aimPos, char, select(2, pcall(function()
                return char:FindFirstChild("HumanoidRootPart") and char.HumanoidRootPart.AssemblyLinearVelocity
            end)))
        end
        if ok and not retry then
            saimConfirm.tries = 0
        end
        return ok == true
    end

    saimFire = function(char)
        if not char then
            return false
        end
        if not saimAlive(localPlayer) then
            return false
        end
        local gun = saimGun()
        if not (gun and gun:FindFirstChild("Shoot")) then
            local hum = localPlayer.Character and localPlayer.Character:FindFirstChildOfClass("Humanoid")
            local bpGun = localPlayer:FindFirstChild("Backpack") and localPlayer.Backpack:FindFirstChild("Gun")
            if hum and bpGun and not (localPlayer.Character and localPlayer.Character:FindFirstChild("Gun")) then
                pcall(function()
                    hum:EquipTool(bpGun)
                end)
                local t0 = os.clock()
                while not (localPlayer.Character and localPlayer.Character:FindFirstChild("Gun")) and os.clock() - t0 < 0.5 do
                    saimRS.Heartbeat:Wait()
                end
            end
        end
        if not saimFovOK(char) then
            return false
        end
        local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
        if not root then
            return false
        end
        if not saimFireSpread(char, nil, true) then
            return false
        end
        return true
    end

    -- подтверждение попадания (GunFired) → обучение interp/hbias/wire
    task.spawn(function()
        local svc
        for _ = 1, 30 do
            pcall(function()
                local cs = game:GetService("ReplicatedStorage"):FindFirstChild("ClientServices")
                svc = cs and cs:FindFirstChild("WeaponService") and cs.WeaponService:FindFirstChild("GunFired")
            end)
            if svc then
                break
            end
            task.wait(1)
        end
        if not (svc and svc:IsA("RemoteEvent")) then
            return
        end
        svc.OnClientEvent:Connect(function(startPart, endPos, hitPart)
            local mine = false
            pcall(function()
                local myChar = localPlayer.Character
                mine = typeof(startPart) == "Instance" and myChar and startPart:IsDescendantOf(myChar) or false
            end)
            if mine then
                saimConfirm.confirmT = os.clock()
                saimConfirm.lastHit = hitPart
                saimConfirm.lastEnd = typeof(endPos) == "Vector3" and endPos or nil
                saimConfirm.lastStart = typeof(startPart) == "Vector3" and startPart or nil
                pcall(saimV3.onFired, startPart, endPos, hitPart)
            end
        end)
        saimConfirm.armed = true
    end)

    -- сэмплер: ping + история позиций цели (обучение предикшна)
    task.spawn(function()
        local nextPing = 0
        while saimAlive(localPlayer) do
            saimRS.Heartbeat:Wait()
            if not (saimCfg.wallbang ~= nil) then
                -- keepalive
            end
            local now = os.clock()
            if now >= nextPing then
                nextPing = now + 0.25
                local p = saimPing()
                if p then
                    saimNet.jit = saimLerp(saimNet.jit, math.abs(p - saimNet.rtt), 0.15)
                    saimNet.rtt = saimLerp(saimNet.rtt, p, 0.25)
                end
            end
            pcall(function()
                local target = saimTargetChar()
                if saimNet.char ~= target then
                    saimNet.char, saimNet.tHist, saimNet.rawHist = target, {}, {}
                end
                local root = target and target:FindFirstChild("HumanoidRootPart")
                if root then
                    local hist = saimNet.tHist
                    local gap = 12
                    if #hist >= 2 then
                        local dt = math.max(hist[#hist].t - hist[#hist - 1].t, 0.016666666666666666)
                        local speed = (hist[#hist].p - hist[#hist - 1].p).Magnitude / dt
                        gap = math.max(12, speed * math.max(now - hist[#hist].t, 0.016666666666666666) * 3 + 8)
                    end
                    if #hist > 0 and (root.Position - hist[#hist].p).Magnitude > gap then
                        hist = {}
                        saimNet.tHist = hist
                    end
                    hist[#hist + 1] = { t = now, p = root.Position }
                    while #hist > 2 and now - hist[1].t > 1.1 do
                        table.remove(hist, 1)
                    end
                    local raw = saimNet.rawHist
                    raw[#raw + 1] = { t = now, p = root.Position }
                    while #raw > 2 and now - raw[1].t > 0.6 do
                        table.remove(raw, 1)
                    end
                end
                local mroot = saimLocalRoot()
                if mroot then
                    local mh = saimNet.mHist
                    mh[#mh + 1] = { t = now, p = mroot.Position }
                    while #mh > 2 and now - mh[1].t > 1.1 do
                        table.remove(mh, 1)
                    end
                end
            end)
        end
    end)

    -- дообучение uplink/hbias по отложенным выстрелам
    task.spawn(function()
        while saimAlive(localPlayer) do
            saimRS.Heartbeat:Wait()
            local pend = saimNet.pend
            if pend and os.clock() - pend.t > 0.7 then
                saimNet.pend = nil
                pcall(function()
                    if typeof(pend.startP) == "Vector3" then
                        local bestDt, bestD, moved = nil, nil, false
                        for _, m in ipairs(saimNet.mHist) do
                            local dt = m.t - pend.t
                            if dt >= -0.02 and dt <= 0.5 then
                                local d = (m.p - pend.startP).Magnitude
                                if not bestD or d < bestD then
                                    bestD, bestDt = d, dt
                                end
                            end
                            if math.abs(m.t - pend.t) < 0.4 and (m.p - pend.startP).Magnitude > 4 then
                                moved = true
                            end
                        end
                        if bestDt and bestD and bestD < 2 and moved then
                            saimNet.up = saimLerp(saimNet.up, math.clamp(bestDt, 0, 0.5), 0.2)
                        end
                    end
                    if typeof(pend.endP) == "Vector3" and pend.rh then
                        local raw = pend.rh
                        local bestIdx, bestD, count = nil, nil, 0
                        for i, h in ipairs(raw) do
                            local dt = h.t - pend.t
                            if dt >= 0.01 and dt <= 0.65 then
                                count = count + 1
                                local d = (h.p - pend.endP).Magnitude
                                if not bestD or d < bestD then
                                    bestD, bestIdx = d, i
                                end
                            end
                        end
                        if bestIdx and bestD and bestD < 6 and count >= 5 then
                            local hp = raw[bestIdx]
                            local ref
                            for i = bestIdx, 1, -1 do
                                if hp.t - raw[i].t >= 0.1 then
                                    ref = raw[i]
                                    break
                                end
                            end
                            local rv = ref and (hp.p - ref.p) / (hp.t - ref.t) or nil
                            local speed = rv and rv.Magnitude or 0
                            if speed >= 8 then
                                local unit = rv.Unit
                                local along = unit:Dot(pend.endP - hp.p)
                                local perp = (pend.endP - hp.p - unit * along).Magnitude
                                local hw = math.clamp((pend.hw or 0.5) * pend.u:Dot(unit) / speed, -0.08, 0.08)
                                local flight = hp.t - pend.t + along / speed + hw
                                if perp < 2.5 and along / speed > -0.06 and along / speed < 0.2 and flight > 0.03 and flight < 0.6 then
                                    local bias = math.clamp(flight - (pend.base or saimRtt() + saimNet.interp), -0.15, 0.2)
                                    if saimNet.hn <= 2 or math.abs(bias - saimNet.hbias) < 0.12 then
                                        saimNet.hbias = saimLerp(saimNet.hbias, bias, saimNet.hn < 3 and 0.4 or 0.15)
                                        saimNet.hn = saimNet.hn + 1
                                    end
                                end
                            end
                        end
                    end
                end)
            end
        end
    end)

    -- перехват обычного клика (Namecall-хук) → тихое перенаправление выстрела
    task.spawn(function()
        local installed = false
        local function tryHook()
            if installed then
                return true
            end
            if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" or type(newcclosure) ~= "function" then
                return false
            end
            local ok = pcall(function()
                local oldNamecall
                local hook = newcclosure(function(self, ...)
                    local method = getnamecallmethod()
                    if method ~= "FireServer" then
                        return oldNamecall(self, ...)
                    end
                    if not (saimCfg.enabled and not getgenv().__taleAimBypass) then
                        return oldNamecall(self, ...)
                    end
                    if checkcaller and checkcaller() then
                        return oldNamecall(self, ...)
                    end
                    local handled = false
                    pcall(function()
                        if self.Name == "Shoot" and self.Parent and self.Parent.Name == "Gun" then
                            local target = saimTargetChar()
                            if target and saimFovOK(target) and saimFireSpread(target, nil, false) then
                                handled = true
                            end
                        end
                    end)
                    if handled then
                        return nil
                    end
                    return oldNamecall(self, ...)
                end)
                oldNamecall = hookmetamethod(game, "__namecall", hook)
            end)
            installed = ok == true
            return installed
        end
        for _ = 1, 10 do
            if tryHook() then
                break
            end
            task.wait(1)
        end
    end)

    -- silentAimShoot: Silent-aim shot
    silentAimShoot = function()
        local character = localPlayer.Character
        if character then
            local player2 = fn72()
            if player2 then
                local humanoidRootPart = player2.Character and player2.Character:FindFirstChild("HumanoidRootPart")
                if humanoidRootPart then
                    task.spawn(function()
                        if fn74(character) then
                            local gun = character:FindFirstChild("Gun")
                            if gun then
                                if forceShotEnabled then
                                    ForceShootAttempt(player2, character, gun)
                                else
                                    if not saimFire(player2.Character) then
                                        local rightHand = character:FindFirstChild("RightHand")
                                        if rightHand then
                                            local position = fn73(player2) or humanoidRootPart.Position
                                            fn75(gun, rightHand.Position, position)
                                        end
                                    end
                                end
                            end
                        end
                    end)
                end
            end
        end
    end
    -- forceShootOnce: Force gun shot once
    forceShootOnce = function()
        if connection4 then
            connection4:Disconnect()
            connection4 = nil
        end
        local character = localPlayer.Character
        local gun = character and character:FindFirstChild("Gun") or localPlayer.Backpack:FindFirstChild("Gun")
        if gun then
            local connection7 = gun.Activated:Connect(function()
                if forceShotEnabled then
                    silentAimShoot()
                end
            end)
            connection4 = connection7
        end
    end;
    (function()
        local tbl6 = {
