        FS_FORCE_BACK_CAP = tbl6.FORCE_BACK_CAP
        FS_FORCE_AHEAD_CAP = tbl6.FORCE_AHEAD_CAP
        FS_FORCE_MIN_BACK = tbl6.FORCE_MIN_BACK
        fsTarget = nil
        fsTrackPart = nil
        fsTrackPos = nil
        fsTrackTime = 0
