        fsTrackStab = 1
        fsRestGap = 3
        fsRestReady = false
        local gravity = workspace.Gravity
        fsSnapT = {}
        fsSnapP = {}
        fsSnapN = 0
        fsSnapI = 0
        fsLeadPing = 0
        fsPingJitter = 0
        fsPingSeen = false
        fsPredOff = Vector3.new(0, 0, 0)
        fsPredStamp = 0
        fsPredFloor = nil
        fsForceAtt = nil
