                task.wait(2)
                local v3 = enabled2
                if enabled2 then
                    v3 = localPlayer.Character == character
                end
                if v3 then
                    local humanoid2 = character:FindFirstChildOfClass("Humanoid")
                    if humanoid2 then
                        humanoid2 = humanoid2.Health > 0
                    end
                    if humanoid2 then
                        enabled2 = false
                        enableAntiAim()
                        pcall(function()
                            local antiAim = uiRefs and uiRefs.AntiAim
                            if antiAim and antiAim.SetValue then
                                antiAim:SetValue(true, true)
                            end
                        end)
                    end
                end
            end)
        elseif antiAimOn then
            disableAntiAim()
            enableAntiAim()
        end
        if pendingAura then
            clearAura()
            setAura(pendingAura.assetId, pendingAura.name)
        end
        if antiflingOn then
            enableAntiFling()
        end
        if jerkOn then
            startJerk()
        end
        if spinOn then
            stopSpin()
            startSpin()
        end
        if wallhopOn then
            startWallhop()
        end
        if customGunModelEnabled then
            applyGunModel()
        end
        if offDamageWater then
            scanMapWater()
        end
        forceShootOnce()
    end)
