    task.spawn(function()
        local ok, decoded = pcall(function()
            return game:GetService("HttpService"):JSONDecode(TH_VALUES_JSON)
        end)
        if not ok or type(decoded) ~= "table" or type(decoded.d) ~= "table" then
            return
        end
