    -- ============ Knife Aimbot (ported settings) ============
    aimbotCfg = aimbotCfg or {
        on = false, mode = "Smart", maxDist = 250, fov = 360,
        wall = true, predict = true, lead = 100, sticky = true,
        marker = true, auto = false, autoRange = 70,
    }
    local aimbotMarker = nil
    local aimbotSticky = nil
    local aimbotRunning = false
    local function aimbotWallClear(fromPos, targetPos, targetChar)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = {localPlayer.Character}
        local res = workspace:Raycast(fromPos, targetPos - fromPos, params)
        if not res then
            return true
        end
        if targetChar and res.Instance and res.Instance:IsDescendantOf(targetChar) then
            return true
        end
        return false
    end
    local function aimbotInFov(pos)
        local cfg = aimbotCfg
        if not cfg.fov or cfg.fov >= 360 then
            return true
        end
        local cam = workspace.CurrentCamera
        if not cam then
            return true
        end
        local toT = pos - cam.CFrame.Position
        if toT.Magnitude < 1e-3 then
            return true
        end
        local ang = math.deg(math.acos(math.clamp(cam.CFrame.LookVector:Dot(toT.Unit), -1, 1)))
        return ang <= (cfg.fov / 2)
    end
    local function aimbotPick()
        local cfg = aimbotCfg
        local char = localPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then
            return nil
        end
        local cam = workspace.CurrentCamera
        local sheriff = findSheriff()
        local murderer = findMurderer()
        local best, bestScore = nil, -math.huge
        for _, plr in ipairs(Players2:GetPlayers()) do
            if plr ~= localPlayer then
                local c = plr.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                local hum = c and c:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local pos = hrp.Position
                    local dist = (pos - root.Position).Magnitude
                    if dist <= cfg.maxDist and aimbotInFov(pos) then
                        if (not cfg.wall) or aimbotWallClear(root.Position, pos, c) then
                            local score
                            if cfg.mode == "Nearest" then
                                score = -dist
                            elseif cfg.mode == "Crosshair" and cam then
                                local sp = cam:WorldToViewportPoint(pos)
                                local px = sp.X - cam.ViewportSize.X * 0.5
                                local py = sp.Y - cam.ViewportSize.Y * 0.5
                                score = -math.sqrt(px * px + py * py)
                            elseif cfg.mode == "Sheriff First" then
                                if plr == sheriff then
                                    score = 1e6
                                elseif plr == murderer then
                                    score = -1e6
                                else
                                    score = -dist
                                end
                            else
                                score = -dist
                                if plr == sheriff then
                                    score = score + 1e5
                                end
                                if plr == murderer then
                                    score = score - 1e5
                                end
                            end
                            if cfg.sticky and plr == aimbotSticky then
                                score = score + 50000
                            end
                            if score > bestScore then
                                bestScore = score
                                best = plr
                            end
                        end
                    end
                end
            end
        end
        return best
    end
    local function aimbotValid(t)
        if not (t and t.Parent and t.Character) then
            return false
        end
        local cfg = aimbotCfg
        local hrp = t.Character:FindFirstChild("HumanoidRootPart")
        local hum = t.Character:FindFirstChildOfClass("Humanoid")
        local char = localPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not (hrp and hum and root) then
            return false
        end
        if hum.Health <= 0 then
            return false
        end
        local pos = hrp.Position
        if (pos - root.Position).Magnitude > cfg.maxDist then
            return false
        end
        if not aimbotInFov(pos) then
            return false
        end
        if cfg.wall and not aimbotWallClear(root.Position, pos, t.Character) then
            return false
        end
        return true
    end
    local function aimbotMarkerUpdate(target)
        if not aimbotCfg.marker then
            if aimbotMarker then
                pcall(function() aimbotMarker:Destroy() end)
                aimbotMarker = nil
            end
            return
        end
        local c = target and target.Character
        if c then
            if aimbotMarker and aimbotMarker.Parent and aimbotMarker.Adornee == c then
                return
            end
            if aimbotMarker then
                pcall(function() aimbotMarker:Destroy() end)
            end
            local hl = Instance.new("Highlight")
            hl.Name = "AimbotMarker"
            hl.Adornee = c
            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            hl.FillTransparency = 0.65
            hl.OutlineTransparency = 0
            hl.FillColor = Color3.fromRGB(224, 116, 24)
            hl.OutlineColor = Color3.fromRGB(224, 116, 24)
            hl.Parent = c
            aimbotMarker = hl
        elseif aimbotMarker then
            pcall(function() aimbotMarker:Destroy() end)
            aimbotMarker = nil
        end
    end
    local function aimbotThrow(target)
        local cfg = aimbotCfg
        local char = localPlayer.Character
        local hand = char and char:FindFirstChild("RightHand")
        local knife = char and char:FindFirstChild("Knife")
        local c = target and target.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        if not (char and hand and knife and hrp) then
            return
        end
        local aimPos
        if cfg.predict then
            aimPos = computeAimPoint(target, cfg.lead / 100)
        else
            aimPos = hrp.Position
        end
        if aimPos and aimPos.Magnitude > 0 then
            pcall(function()
                knife.Events.KnifeThrown:FireServer(CFrame.new(hand.Position), CFrame.new(aimPos))
            end)
        end
    end
    aimbotStop = function()
        aimbotRunning = false
        if aimbotMarker then
            pcall(function() aimbotMarker:Destroy() end)
            aimbotMarker = nil
        end
        aimbotSticky = nil
    end
    aimbotStart = function()
        aimbotStop()
        aimbotRunning = true
        task.spawn(function()
            local cooldown = 0
            while aimbotRunning do
                task.wait(0.12)
                pcall(function()
                    if findMurderer() ~= localPlayer then
                        return
                    end
                    local char = localPlayer.Character
                    if not (char and char:FindFirstChild("Knife")) then
                        return
                    end
                    if not aimbotValid(aimbotSticky) then
                        aimbotSticky = aimbotPick()
                    end
                    local target = aimbotSticky
                    aimbotMarkerUpdate(target)
                    cooldown = math.max(0, cooldown - 0.12)
                    if aimbotCfg.auto and target and cooldown <= 0 then
                        local hrp = target.Character:FindFirstChild("HumanoidRootPart")
                        local root = char:FindFirstChild("HumanoidRootPart")
                        if hrp and root then
                            local dist = (hrp.Position - root.Position).Magnitude
                            if dist <= aimbotCfg.autoRange then
                                if (not aimbotCfg.wall) or aimbotWallClear(root.Position, hrp.Position, target.Character) then
                                    aimbotThrow(target)
                                    cooldown = 1.2
                                end
                            end
                        end
                    end
                end)
            end
        end)
    end
