            ["WraithKnife"] = { Image = "rbxthumb://type=Asset&w=150&h=150&id=107190526940939", ItemID = 107190526940939, ItemName = "Spirit", ItemType = "Knife", Rarity = "Godly" },
            ["XenoGun"] = { Image = "rbxthumb://type=Asset&w=150&h=150&id=96859273002742", ItemID = 79722325448464, ItemName = "Xenoshot", ItemType = "Gun", Rarity = "Godly" },
            ["XenoKnife"] = { Image = "rbxthumb://type=Asset&w=150&h=150&id=115021756767182", ItemID = 100576599313371, ItemName = "Xenoknife", ItemType = "Knife", Rarity = "Godly" },
            ["Xmas"] = { Image = "rbxthumb://type=Asset&w=150&h=150&id=332077449", ItemID = 473572568, ItemName = "Xmas", ItemType = "Knife", Rarity = "Godly" },
            ["YellowSeer"] = { Image = "rbxthumb://type=Asset&w=150&h=150&id=3184139648", ItemID = 3184124768, ItemName = "Yellow Seer", ItemType = "Knife", Rarity = "Godly" },
            ["ZombieBat"] = { Image = "rbxthumb://type=Asset&w=150&h=150&id=11229814357", ItemID = 11229814357, ItemName = "Bat", ItemType = "Knife", Rarity = "Godly" },
        }
        local catalogByName = {}
        for _, item in pairs(SKIN_CATALOG) do
            if type(item) == "table" and type(item.ItemName) == "string" then
                catalogByName[item.ItemName] = item
            end
        end
        local skinByKey = {}
        local skinListGun, skinListKnife = {}, {}
        for key, db in pairs(SKIN_MESH_DB) do
            if type(db.mesh) == "string" and type(db.kind) == "string" then
                local cat = SKIN_CATALOG[key]
                if type(cat) ~= "table" then
                    cat = catalogByName[db.name or key]
                end
                local image = ""
                if type(cat) == "table" and type(cat.Image) == "string" and cat.Image ~= "" then
                    image = cat.Image
                elseif tonumber(db.itemid) then
                    image = "rbxthumb://type=Asset&w=150&h=150&id=" .. tostring(db.itemid)
                end
                local entry = {
                    key = key,
                    name = db.name or key,
                    kind = db.kind,
                    rarity = db.rarity or "Common",
                    image = image,
                }
                skinByKey[key] = entry
                if db.kind == "Gun" then
                    skinListGun[#skinListGun + 1] = entry
                else
                    skinListKnife[#skinListKnife + 1] = entry
                end
            end
        end
        table.sort(skinListGun, function(a, b)
            return a.name < b.name
        end)
        table.sort(skinListKnife, function(a, b)
            return a.name < b.name
        end)
        -- ---- skin engine: mesh/texture override with backup, grip, holster attachment, HUD icons ----
        local function skinDisplayObj(character, slot)
            local ref = character:FindFirstChild("DisplayRef" .. slot)
            if ref and ref:IsA("ObjectValue") and ref.Value and ref.Value.Parent then
                return ref.Value
            end
            return character:FindFirstChild(slot .. "Display")
        end
        local function skinAnchor(container)
            if not container then
                return nil
            end
            if container:IsA("Tool") then
                local handle = container:FindFirstChild("Handle")
                if handle and handle:IsA("BasePart") then
                    return handle
                end
            end
            if container:IsA("BasePart") then
                return container
            end
            local handle = container:FindFirstChild("Handle", true)
            if handle and handle:IsA("BasePart") then
                return handle
            end
            return container:FindFirstChildWhichIsA("BasePart", true)
        end
        local function skinTargets(kind)
            local list, seen = {}, {}
            local function add(inst)
                if inst and not seen[inst] then
                    seen[inst] = true
                    list[#list + 1] = inst
                end
            end
            local character = localPlayer.Character
            local backpack = localPlayer:FindFirstChildOfClass("Backpack")
            local slot = kind == "Gun" and "Gun" or "Knife"
            if character then
                add(skinDisplayObj(character, slot))
                add(character:FindFirstChild(slot))
                add(character:FindFirstChild(slot .. "Display"))
            end
            if backpack then
                add(backpack:FindFirstChild(slot))
            end
            return list
        end
        local function skinApplyMesh(kind, db)
            local ok = false
            for _, target in ipairs(skinTargets(kind)) do
                local part = skinAnchor(target)
                if part then
                    pcall(function()
                        if part:IsA("MeshPart") then
                            if part:GetAttribute("TALEOrigMesh") == nil then
                                part:SetAttribute("TALEOrigMesh", part.MeshId)
                                part:SetAttribute("TALEOrigTex", part.TextureID)
                            end
                            part.MeshId = db.mesh
                            if db.tex ~= "" then
                                part.TextureID = db.tex
                            end
                        else
                            local mesh = part:FindFirstChildOfClass("SpecialMesh")
                            if not mesh then
                                mesh = Instance.new("SpecialMesh")
                                mesh.MeshType = Enum.MeshType.FileMesh
                                mesh.Name = "Mesh"
                                mesh.Parent = part
                            end
                            if mesh:GetAttribute("TALEOrigMesh") == nil then
                                mesh:SetAttribute("TALEOrigMesh", mesh.MeshId)
                                mesh:SetAttribute("TALEOrigTex", mesh.TextureId)
                            end
                            mesh.MeshId = db.mesh
                            if db.tex ~= "" then
                                mesh.TextureId = db.tex
                            end
                            mesh.Scale = Vector3.new(db.sx or 1, db.sy or 1, db.sz or 1)
                        end
                    end)
                    ok = true
                end
            end
            return ok
        end
        local function skinRestoreKind(kind)
            local slot = kind == "Gun" and "Gun" or "Knife"
            local function restore(container)
                if not container then
                    return
                end
                local list = container:GetDescendants()
                list[#list + 1] = container
                for _, item in ipairs(list) do
                    local origMesh = item:GetAttribute("TALEOrigMesh")
                    if origMesh ~= nil then
                        pcall(function()
                            item.MeshId = origMesh
                            local origTex = item:GetAttribute("TALEOrigTex")
                            if origTex ~= nil then
                                if item:IsA("MeshPart") then
                                    item.TextureID = origTex
                                else
                                    item.TextureId = origTex
                                end
                            end
                        end)
                    end
                    local origGrip = item:GetAttribute("TALEOrigGrip")
                    if origGrip ~= nil and item:IsA("Tool") then
                        pcall(function()
                            item.Grip = origGrip
                        end)
                    end
                end
            end
            for _, target in ipairs(skinTargets(kind)) do
                restore(target)
            end
            local character = localPlayer.Character
            if character then
                restore(skinDisplayObj(character, slot))
            end
        end
        local function skinApplyGrip(kind, db)
            local grip = db.grip
            if type(grip) ~= "table" or #grip < 12 then
                return
            end
            pcall(function()
                local slot = kind == "Gun" and "Gun" or "Knife"
                local function setGrip(tool)
                    if tool and tool:IsA("Tool") then
                        if tool:GetAttribute("TALEOrigGrip") == nil then
                            tool:SetAttribute("TALEOrigGrip", tool.Grip)
                        end
                        tool.Grip = CFrame.new(grip[1], grip[2], grip[3], grip[4], grip[5], grip[6], grip[7], grip[8], grip[9], grip[10], grip[11], grip[12])
                    end
                end
                local character = localPlayer.Character
                local backpack = localPlayer:FindFirstChildOfClass("Backpack")
                if character then
                    setGrip(character:FindFirstChild(slot))
                end
                if backpack then
                    setGrip(backpack:FindFirstChild(slot))
                end
            end)
        end
        local function skinApplyHolster(kind, db)
            local acf = db.acf
            if type(acf) ~= "table" or #acf < 12 then
                return
            end
            pcall(function()
                local character = localPlayer.Character
                if not character then
                    return
                end
                local slot = kind == "Gun" and "Gun" or "Knife"
                local display = skinDisplayObj(character, slot) or character:FindFirstChild(slot .. "Display")
                if not display then
                    return
                end
                local att = (type(db.att) == "string" and db.att ~= "" and display:FindFirstChild(db.att, true))
                    or display:FindFirstChild("CustomAttachment", true)
                    or display:FindFirstChild("Attachment", true)
                    or display:FindFirstChildWhichIsA("Attachment", true)
                if att and att:IsA("Attachment") then
                    att.CFrame = CFrame.new(acf[1], acf[2], acf[3], acf[4], acf[5], acf[6], acf[7], acf[8], acf[9], acf[10], acf[11], acf[12])
                end
            end)
        end
        local skinHudIcons = {Equip = nil, Throw = nil}
        local function skinSetIconTree(obj, image)
            if not obj then
                return
            end
            if obj:IsA("ImageButton") or obj:IsA("ImageLabel") then
                obj.Image = image
            end
            for _, child in ipairs(obj:GetChildren()) do
                if child:IsA("ImageButton") or child:IsA("ImageLabel") then
                    child.Image = image
                end
            end
        end
        local function skinCacheHudIcons()
            local equip = skinHudIcons.Equip
            local throwIcon = skinHudIcons.Throw
            if equip and equip.Parent and throwIcon and throwIcon.Parent then
                return
            end
            local playerGui = localPlayer:FindFirstChild("PlayerGui")
            if not playerGui then
                return
            end
            pcall(function()
                local roots = {}
                for _, name in ipairs({"MainGUI", "MainGui", "HUD", "GameGUI"}) do
                    local gui = playerGui:FindFirstChild(name)
                    if gui then
                        roots[#roots + 1] = gui
                    end
                end
                if #roots == 0 then
                    for _, gui in ipairs(playerGui:GetChildren()) do
                        if gui:IsA("ScreenGui") and gui.Name ~= "SkinsContent" then
                            roots[#roots + 1] = gui
                            if #roots >= 2 then
                                break
                            end
                        end
                    end
                end
                for _, root in ipairs(roots) do
                    for _, descendant in ipairs(root:GetDescendants()) do
                        if descendant:IsA("TextLabel") or descendant:IsA("TextButton") then
                            local text = string.lower(string.gsub(descendant.Text or "", "%s+", ""))
                            if text == "equip" or text == "throw" then
                                local imageObject = descendant
                                while imageObject and not (imageObject:IsA("ImageButton") or imageObject:IsA("ImageLabel")) do
                                    imageObject = imageObject.Parent
                                end
                                if imageObject then
                                    if text == "equip" then
                                        skinHudIcons.Equip = imageObject
                                    else
                                        skinHudIcons.Throw = imageObject
                                    end
                                end
                            end
                        end
                    end
                end
            end)
        end
        local function skinApplyIcons(kind, image)
            if type(image) ~= "string" or image == "" then
                return
            end
            pcall(function()
                local slot = kind == "Gun" and "Gun" or "Knife"
                local function setIcon(tool)
                    if tool and tool:IsA("Tool") then
                        tool.TextureId = image
                    end
                end
                local character = localPlayer.Character
                local backpack = localPlayer:FindFirstChildOfClass("Backpack")
                if character then
                    setIcon(character:FindFirstChild(slot))
                end
                if backpack then
                    setIcon(backpack:FindFirstChild(slot))
                end
            end)
            skinCacheHudIcons()
            pcall(function()
                if kind == "Gun" then
                    skinSetIconTree(skinHudIcons.Equip, image)
                else
                    skinSetIconTree(skinHudIcons.Throw, image)
                end
            end)
        end
        local function skinApplyKind(kind, key)
            local db = key and SKIN_MESH_DB[key]
            if not db then
                return false
            end
            skinApplyMesh(kind, db)
            skinApplyGrip(kind, db)
            skinApplyHolster(kind, db)
            local entry = skinByKey[key]
            if entry then
                skinApplyIcons(kind, entry.image)
            end
            return true
        end
        local skinApplying = false
        local function skinApplyConfigured()
            if skinApplying or not (selectedGunSkin or selectedKnifeSkin) then
                return
            end
            skinApplying = true
            pcall(function()
                if selectedKnifeSkin then
                    skinApplyKind("Knife", selectedKnifeSkin)
                end
                if selectedGunSkin then
                    skinApplyKind("Gun", selectedGunSkin)
                end
            end)
            skinApplying = false
        end
        -- keep-alive: the game recreates weapons each round, re-apply the selected skins
        local skinKeepQueued = false
        local function skinQueueKeep()
            if skinKeepQueued or not (selectedGunSkin or selectedKnifeSkin) then
                return
            end
            skinKeepQueued = true
            task.delay(0.4, function()
                skinKeepQueued = false
                skinApplyConfigured()
            end)
        end
        local function skinHookCharacter(character)
            if not character then
                return
            end
            character.ChildAdded:Connect(skinQueueKeep)
        end
        skinHookCharacter(localPlayer.Character)
        localPlayer.CharacterAdded:Connect(function(character)
            skinHudIcons.Equip, skinHudIcons.Throw = nil, nil
            skinHookCharacter(character)
            task.delay(0.4, function()
                skinApplyConfigured()
            end)
        end)
        pcall(function()
            local backpack = localPlayer:WaitForChild("Backpack", 5)
            if backpack then
                backpack.ChildAdded:Connect(skinQueueKeep)
            end
        end)
        local skinAcc = 0
        RunService.Heartbeat:Connect(function(dt)
            if not (selectedGunSkin or selectedKnifeSkin) then
                return
            end
            skinAcc = skinAcc + dt
            if skinAcc < 3 then
                return
            end
            skinAcc = 0
            skinApplyConfigured()
        end)
        -- ---- menu: kind switch + search + virtual card grid (Emotes style) ----
        local skinsSection = skinsTab:AddSection({Name = "Skins", Position = "left"})
        local content = skinsSection.Section.Items.Content.Instance
        local skinsState = {kind = "Gun", query = "", filtered = {}, cards = {}}
        local skinRarityColors = {
            Ancient = Color3.fromRGB(255, 105, 120),
            Legendary = Color3.fromRGB(170, 90, 255),
            Godly = Color3.fromRGB(255, 170, 54),
            Classic = Color3.fromRGB(90, 160, 255),
            Unique = Color3.fromRGB(120, 200, 160),
            Common = Color3.fromRGB(150, 145, 140),
        }
        local kindGunButton, kindKnifeButton = nil, nil
        local function repaintKindButtons()
            local theme = UI.Theme or {}
            local accent = theme.Accent or Color3.fromRGB(224, 116, 24)
            local element = theme.Element or Color3.fromRGB(15, 13, 11)
            local text = theme.Text or Color3.fromRGB(245, 242, 238)
            for _, pair in ipairs({{kindGunButton, "Gun"}, {kindKnifeButton, "Knife"}}) do
                local button = pair[1]
                local active = skinsState.kind == pair[2]
                button.BackgroundColor3 = active and accent or element
                button.TextColor3 = active and text or Color3.fromRGB(150, 145, 140)
            end
        end
        local kindFrame = Instance.new("Frame")
        kindFrame.Size = UDim2.new(1, 0, 0, 26)
        kindFrame.BackgroundTransparency = 1
        kindFrame.LayoutOrder = 1
        kindFrame.ZIndex = 6
        kindFrame.Parent = content
        local kindLayout = Instance.new("UIListLayout")
        kindLayout.FillDirection = Enum.FillDirection.Horizontal
        kindLayout.Padding = UDim.new(0, 6)
        kindLayout.SortOrder = Enum.SortOrder.LayoutOrder
        kindLayout.Parent = kindFrame
        local function makeKindButton(text, kind, order)
            local button = Instance.new("TextButton")
            button.Size = UDim2.new(0, 96, 0, 26)
            button.LayoutOrder = order
            button.AutoButtonColor = false
            button.BorderSizePixel = 0
            button.Font = Enum.Font.GothamBold
            button.TextSize = 11
            button.Text = text
            button.ZIndex = 7
            button.Parent = kindFrame
            Instance.new("UICorner", button).CornerRadius = UDim.new(0, 6)
            button.Activated:Connect(function()
                if skinsState.kind ~= kind then
                    skinsState.kind = kind
                    repaintKindButtons()
                    skinsState.refresh()
                end
            end)
            return button
        end
        kindGunButton = makeKindButton("Guns", "Gun", 1)
        kindKnifeButton = makeKindButton("Knives", "Knife", 2)
        local searchBox = Instance.new("TextBox")
        searchBox.Name = "SkinsSearch"
        searchBox.Size = UDim2.new(1, 0, 0, 30)
        searchBox.BackgroundColor3 = Color3.fromRGB(15, 13, 11)
        searchBox.BackgroundTransparency = 0.1
        searchBox.BorderSizePixel = 0
        searchBox.ClearTextOnFocus = false
        searchBox.Font = Enum.Font.Gotham
        searchBox.PlaceholderText = "Search Skins..."
        searchBox.PlaceholderColor3 = Color3.fromRGB(150, 145, 140)
        searchBox.Text = ""
        searchBox.TextColor3 = UI.Theme and UI.Theme.Text or Color3.fromRGB(245, 242, 238)
        searchBox.TextSize = 11
        searchBox.TextXAlignment = Enum.TextXAlignment.Left
        searchBox.LayoutOrder = 2
        searchBox.ZIndex = 6
        searchBox.Parent = content
        Instance.new("UICorner", searchBox).CornerRadius = UDim.new(0, 6)
        local searchPadding = Instance.new("UIPadding")
        searchPadding.PaddingLeft = UDim.new(0, 9)
        searchPadding.PaddingRight = UDim.new(0, 7)
        searchPadding.Parent = searchBox
        local scrollingFrame = Instance.new("ScrollingFrame")
        scrollingFrame.Name = "SkinsCards"
        scrollingFrame.Size = UDim2.new(1, 0, 0, 237)
        scrollingFrame.BackgroundColor3 = Color3.fromRGB(10, 9, 8)
        scrollingFrame.BackgroundTransparency = 0.35
        scrollingFrame.BorderSizePixel = 0
        scrollingFrame.ScrollBarThickness = 3
        scrollingFrame.ScrollBarImageColor3 = UI.Theme and UI.Theme.Accent or Color3.fromRGB(224, 116, 24)
        scrollingFrame.Active = true
        scrollingFrame.AutomaticCanvasSize = Enum.AutomaticSize.None
        scrollingFrame.CanvasSize = UDim2.new(0, 0, 0, 0)
        scrollingFrame.ScrollingDirection = Enum.ScrollingDirection.Y
        scrollingFrame:SetAttribute("SkipPageFade", true)
        scrollingFrame.LayoutOrder = 3
        scrollingFrame.ZIndex = 4
        scrollingFrame.Parent = content
        Instance.new("UICorner", scrollingFrame).CornerRadius = UDim.new(0, 7)
        local gridPadding = Instance.new("UIPadding")
        gridPadding.PaddingTop = UDim.new(0, 7)
        gridPadding.PaddingLeft = UDim.new(0, 7)
        gridPadding.PaddingRight = UDim.new(0, 7)
        gridPadding.PaddingBottom = UDim.new(0, 7)
        gridPadding.Parent = scrollingFrame
        local CARD_HEIGHT = 72
        local CARD_GAP = 7
        local CARD_COLUMNS = 2
        local function currentSkinKey()
            return skinsState.kind == "Gun" and selectedGunSkin or selectedKnifeSkin
        end
        local function paintCard(cardEntry, entry, selected)
            local theme = UI.Theme or {}
            cardEntry.Stroke.Color = theme.Accent or Color3.fromRGB(224, 116, 24)
            cardEntry.Stroke.Enabled = selected
            cardEntry.Stroke.Thickness = selected and 2 or 1
            cardEntry.Card.BackgroundColor3 = selected and (theme.Element or Color3.fromRGB(15, 13, 11)) or Color3.fromRGB(15, 13, 11)
            cardEntry.Card.BackgroundTransparency = selected and 0.02 or 0.18
            cardEntry.Title.TextColor3 = selected and (theme["Light Accent"] or Color3.fromRGB(255, 170, 54)) or (theme.Text or Color3.fromRGB(245, 242, 238))
            local rarityColor = skinRarityColors[entry.rarity] or skinRarityColors.Common
            cardEntry.Marker.BackgroundColor3 = rarityColor
            cardEntry.Rarity.TextColor3 = rarityColor
            if entry.image ~= "" then
                cardEntry.Thumb.Image = entry.image
            else
                cardEntry.Thumb.Image = "rbxasset://textures/ui/GuiImagePlaceholder.png"
            end
        end
        local function layoutCards()
            local start = (math.max(0, math.floor(scrollingFrame.CanvasPosition.Y / (CARD_HEIGHT + CARD_GAP)) - 1)) * CARD_COLUMNS + 1
            local selectedKey = currentSkinKey()
            for i, cardEntry in ipairs(skinsState.cards) do
                local entry = skinsState.filtered[start + i - 1]
                if entry then
                    local index = start + i - 2
                    local col = index % CARD_COLUMNS
                    cardEntry.Entry = entry
                    cardEntry.Card.Position = UDim2.new(col / CARD_COLUMNS, col == 0 and 0 or 3, 0, math.floor(index / CARD_COLUMNS) * (CARD_HEIGHT + CARD_GAP) + 7)
                    cardEntry.Card.Visible = true
                    cardEntry.Title.Text = entry.name
                    cardEntry.Rarity.Text = entry.rarity
                    paintCard(cardEntry, entry, entry.key == selectedKey)
                else
                    cardEntry.Entry = nil
                    cardEntry.Card.Visible = false
                end
            end
        end
        skinsState.refresh = function()
            table.clear(skinsState.filtered)
            local source = skinsState.kind == "Gun" and skinListGun or skinListKnife
            local query = skinsState.query
            for _, entry in ipairs(source) do
                if query == "" or string.find(string.lower(entry.name), query, 1, true) then
                    skinsState.filtered[#skinsState.filtered + 1] = entry
                end
            end
            local rows = math.ceil(#skinsState.filtered / CARD_COLUMNS)
            scrollingFrame.CanvasSize = UDim2.new(0, 0, 0, rows * (CARD_HEIGHT + CARD_GAP) + 14)
            local maxY = math.max(0, scrollingFrame.CanvasSize.Y.Offset - scrollingFrame.AbsoluteSize.Y)
            if scrollingFrame.CanvasPosition.Y > maxY then
                scrollingFrame.CanvasPosition = Vector2.new(0, maxY)
            end
            layoutCards()
        end
        local function skinsSelect(entry)
            if currentSkinKey() == entry.key then
                if entry.kind == "Gun" then
                    selectedGunSkin = nil
                else
                    selectedKnifeSkin = nil
                end
                skinRestoreKind(entry.kind)
                tbl3.new({Title = "Skins", Content = "Default", Duration = 2})
            else
                if entry.kind == "Gun" then
                    selectedGunSkin = entry.key
                else
                    selectedKnifeSkin = entry.key
                end
                skinApplyKind(entry.kind, entry.key)
                tbl3.new({Title = "Skins", Content = entry.name, Duration = 2})
            end
            skinsState.refresh()
        end
        for i = 1, 16 do
            local card = Instance.new("TextButton")
            card.Name = "SkinsVirtualCard" .. i
            card.Size = UDim2.new(0.5, -4, 0, CARD_HEIGHT)
            card.AutoButtonColor = false
            card.BackgroundColor3 = Color3.fromRGB(15, 13, 11)
            card.BackgroundTransparency = 0.18
            card.BorderSizePixel = 0
            card.Text = ""
            card.Visible = false
            card.ZIndex = 5
            card.Parent = scrollingFrame
            Instance.new("UICorner", card).CornerRadius = UDim.new(0, 7)
            local stroke = Instance.new("UIStroke", card)
            stroke.Color = UI.Theme and UI.Theme.Accent or Color3.fromRGB(224, 116, 24)
            stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            stroke.Thickness = 1
            stroke.Enabled = false
            local marker = Instance.new("Frame")
            marker.Name = "RarityMarker"
            marker.Size = UDim2.new(0, 4, 1, -16)
            marker.Position = UDim2.new(0, 7, 0, 8)
            marker.BorderSizePixel = 0
            marker.ZIndex = 6
            marker.Parent = card
            Instance.new("UICorner", marker).CornerRadius = UDim.new(0, 2)
            local thumb = Instance.new("ImageLabel")
            thumb.Name = "Thumb"
            thumb.Size = UDim2.new(0, 44, 0, 44)
            thumb.Position = UDim2.new(0, 18, 0.5, 0)
            thumb.AnchorPoint = Vector2.new(0, 0.5)
            thumb.BackgroundTransparency = 1
            thumb.ScaleType = Enum.ScaleType.Crop
            thumb.ZIndex = 6
            thumb.Parent = card
            Instance.new("UICorner", thumb).CornerRadius = UDim.new(0, 5)
            local title = Instance.new("TextLabel")
            title.Name = "Title"
            title.Size = UDim2.new(1, -110, 0, 22)
            title.Position = UDim2.new(0, 68, 0, 16)
            title.BackgroundTransparency = 1
            title.Font = Enum.Font.GothamBold
            title.TextColor3 = UI.Theme and UI.Theme.Text or Color3.fromRGB(245, 242, 238)
            title.TextSize = 11
            title.TextXAlignment = Enum.TextXAlignment.Left
            title.TextTruncate = Enum.TextTruncate.AtEnd
            title.ZIndex = 6
            title.Parent = card
            local rarity = Instance.new("TextLabel")
            rarity.Name = "Rarity"
            rarity.Size = UDim2.new(1, -110, 0, 12)
            rarity.Position = UDim2.new(0, 68, 0, 40)
            rarity.BackgroundTransparency = 1
            rarity.Font = Enum.Font.Gotham
